set -eu; umask 077; home=$1; base=$2; pro=$3; mode=$4; cli=$5; shift 5; [ "$mode" != refuse ] || { echo "Export marker missing or unmanaged folder refused"; exit 1; }; home=$(cd "$home" && pwd -P); project=$(cd "$(dirname "$pro")" && pwd -P); [ ! -L "$home/exports" ] || { echo 'Symlinked exports folder refused'; exit 1; }; mkdir -p "$home/exports"; case "$base" in "$home/exports/"*) leaf=${base#"$home/exports/"};; *) echo 'Export outside managed root refused'; exit 1;; esac; case "$leaf" in ''|*[!a-zA-Z0-9_-]*) echo 'Unsafe export name'; exit 1;; esac; case "$base/" in "$project/"*) echo 'Export must be outside the project'; exit 1;; esac; [ ! -L "$base" ] || { echo 'Symlinked export base refused'; exit 1; }; if mkdir "$base" 2>/dev/null; then printf '%s\n' backplane-export >"$base/.backplane-export"; fi; [ -f "$base/.backplane-export" ] && [ ! -L "$base/.backplane-export" ] || { echo 'Unmarked export folder refused'; exit 1; }; [ ! -L "$base/report.json" ] && [ ! -L "$base/kicad10" ] || { echo 'Symlinked export content refused'; exit 1; }; mkdir "$base/.busy" 2>/dev/null || { echo 'Export already running in this folder'; exit 1; }; trap 'rmdir "$base/.busy"' EXIT; if [ "$mode" = export ]; then rm -rf -- "$base/kicad10"; else rm -f -- "$base/report.json"; fi; "$cli" project downgrade --target 10.0 --report-json "$base/report.json" -o "$base/kicad10" "$pro" "$@"